-- Stores the frozen A8Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a8q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A8Q';
 v_cp constant text := 'A8Q_C2';
 v_wi constant bigint := 1118;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A8Q_C2';
 v_packet_sha constant text := '967dd1e0ef2274dc8d7dae8536816ca4d309a98ce81773b481e64b1356ff1213';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"criteria":["decision_stable","front_accounting_complete","decision_changing_questions_open"],"decisions":["STOP","CONTINUE","REQUIRES_DECISION","BLOCKED"],"forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001","stop_forbidden_while_fronts_blocked":true,"trace_keys":["blockers","effect_on_decision","front_id"]},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a7_stage_output\": {\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"A6-REQ-001\",\n      \"A6-REQ-002\",\n      \"A6-REQ-003\",\n      \"A6-REQ-004\",\n      \"A6-REQ-005\",\n      \"dimension:functional\",\n      \"dimension:data\",\n      \"dimension:permissions\",\n      \"dimension:state\",\n      \"dimension:errors\",\n      \"dimension:side_effects\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\",\n    \"material_fronts\": [\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\",\n          \"decision:A5-DEC-001\",\n          \"decision:A5-DEC-003\"\n        ],\n        \"front_id\": \"A7-FRONT-001\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\",\n        \"scope_ids\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-004\",\n          \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n          \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-002\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\",\n        \"scope_ids\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-003\",\n          \"dimension:state\",\n          \"decision:A5-DEC-003\",\n          \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-003\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\",\n        \"scope_ids\": [\n          \"A6-REQ-003\",\n          \"dimension:state\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-003\",\n          \"decision:A5-DEC-004\"\n        ],\n        \"front_id\": \"A7-FRONT-004\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\",\n        \"scope_ids\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-005\",\n          \"decision:A5-DEC-004\",\n          \"decision:A5-DEC-005\",\n          \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n        ],\n        \"front_id\": \"A7-FRONT-005\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\",\n        \"scope_ids\": [\n          \"A6-REQ-005\"\n        ]\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A7_FRONTS_OUTPUT_V1\"\n  }\n}","input_origin":"A7Q_C2 GPT Native RAW (raw_output_sha256 6bbeadcc8ac1c69d239aec02af75d6a0e153a745c1954703e6c4811c001173fa)","input_sha256":"6ff3b7e34aaeaf95ecfca1b21376b7b313140eee2b538251cdea0da110094ed7","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","research_decision","stop_criteria","front_trace","owner_decisions_required","evidence_refs","no_ready_claim","decision_statement"],"schema":"A8_RESEARCH_DECISION_OUTPUT_V1","validator":"analysis_qualification_a8q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"967dd1e0ef2274dc8d7dae8536816ca4d309a98ce81773b481e64b1356ff1213","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A8 (decisión de investigación) del perfil de análisis. Recibes la salida de la etapa A7 (abajo). Decide si la investigación puede detenerse. STOP solo es admisible con decisión estable, contabilidad de frentes completa y ninguna pregunta sin resolver que pueda cambiar el resultado; si no se cumple, elige CONTINUE, REQUIRES_DECISION o BLOCKED según corresponda. No declares READY ni resuelvas decisiones del propietario. Referencias válidas: las evidence_refs de la entrada y 'front:<front_id>' para cada frente. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, research_decision, stop_criteria, front_trace, owner_decisions_required, evidence_refs, no_ready_claim, decision_statement. schema_version='A8_RESEARCH_DECISION_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. research_decision: STOP|CONTINUE|REQUIRES_DECISION|BLOCKED. stop_criteria: objeto con exactamente las claves booleanas decision_stable, front_accounting_complete, decision_changing_questions_open. front_trace: lista con un elemento por cada frente de la entrada, {front_id, blockers (lista de decision_id del frente), effect_on_decision (texto)}. owner_decisions_required: lista de decision_id de la entrada que el propietario debe resolver (todas las que bloquean algún frente). evidence_refs: lista no vacía de referencias válidas. no_ready_claim=true. decision_statement: texto que explica la decisión y por qué no es STOP si corresponde.\n\nENTRADA (JSON):\n{\n  \"a7_stage_output\": {\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"A6-REQ-001\",\n      \"A6-REQ-002\",\n      \"A6-REQ-003\",\n      \"A6-REQ-004\",\n      \"A6-REQ-005\",\n      \"dimension:functional\",\n      \"dimension:data\",\n      \"dimension:permissions\",\n      \"dimension:state\",\n      \"dimension:errors\",\n      \"dimension:side_effects\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\",\n    \"material_fronts\": [\n      {\n        \"blockers\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\",\n          \"decision:A5-DEC-001\",\n          \"decision:A5-DEC-003\"\n        ],\n        \"front_id\": \"A7-FRONT-001\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\",\n        \"scope_ids\": [\n          \"A6-REQ-001\",\n          \"dimension:functional\",\n          \"dimension:permissions\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-004\",\n          \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n          \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-002\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\",\n        \"scope_ids\": [\n          \"A6-REQ-002\",\n          \"A6-REQ-004\",\n          \"dimension:data\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-003\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-003\",\n          \"dimension:state\",\n          \"decision:A5-DEC-003\",\n          \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n        ],\n        \"front_id\": \"A7-FRONT-003\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\",\n        \"scope_ids\": [\n          \"A6-REQ-003\",\n          \"dimension:state\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\",\n          \"decision:A5-DEC-002\",\n          \"decision:A5-DEC-003\",\n          \"decision:A5-DEC-004\"\n        ],\n        \"front_id\": \"A7-FRONT-004\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\",\n        \"scope_ids\": [\n          \"dimension:errors\",\n          \"dimension:side_effects\"\n        ]\n      },\n      {\n        \"blockers\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"closure\": \"BLOCKED\",\n        \"evidence_refs\": [\n          \"A6-REQ-005\",\n          \"decision:A5-DEC-004\",\n          \"decision:A5-DEC-005\",\n          \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n        ],\n        \"front_id\": \"A7-FRONT-005\",\n        \"obligation_mode\": \"REQUIRED\",\n        \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\",\n        \"scope_ids\": [\n          \"A6-REQ-005\"\n        ]\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A7_FRONTS_OUTPUT_V1\"\n  }\n}","request_sha256":"4b27dc75b21f17f5fc86ee7816cf773f1ddd7bc44979e0c08a4c2b55f8fb8bbb","run_id":"A8Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A8","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A8Q/A8Q_C2","unit":"A8"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A8Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A8Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A8Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A8Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A8Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A8Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A8Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A8Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A8Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A8Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A8Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A8Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A8Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A8Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A8Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A8Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A8Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a8q_c2_prep$;
COMMIT;
